"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["8491"],{7831(n,e,i){i.r(e),i.d(e,{metadata:()=>t,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>c});var t=JSON.parse('{"id":"spec/introduction","title":"1. Introduction","description":"Purpose and scope of the CADL specification, the challenges of SoS institutional design that motivate the language, and an introductory glossary.","source":"@site/docs/spec/01-introduction.md","sourceDirName":"spec","slug":"/spec/introduction","permalink":"/cadl-spec/docs/spec/introduction","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"1. Introduction","description":"Purpose and scope of the CADL specification, the challenges of SoS institutional design that motivate the language, and an introductory glossary."},"sidebar":"specSidebar","previous":{"title":"CADL Specification v0.3","permalink":"/cadl-spec/docs/spec/intro"},"next":{"title":"2. Language Objectives","permalink":"/cadl-spec/docs/spec/objectives"}}'),a=i(4848),o=i(8453);let s={sidebar_position:1,title:"1. Introduction",description:"Purpose and scope of the CADL specification, the challenges of SoS institutional design that motivate the language, and an introductory glossary."},r,c={},l=[{value:"1.1 Purpose and Scope",id:"11-purpose-and-scope",level:2},{value:"1.2 Background: Challenges of Institutional Design in SoS",id:"12-background-challenges-of-institutional-design-in-sos",level:2},{value:"Objective 1: Making SoS Institutional Design Computationally Tractable",id:"objective-1-making-sos-institutional-design-computationally-tractable",level:3},{value:"Objective 2: Computing Institutional Violations and Contradictions",id:"objective-2-computing-institutional-violations-and-contradictions",level:3},{value:"Objective 3: Automatic Conversion from Institutional Design to Control Logic, Optimization, and Code Generation",id:"objective-3-automatic-conversion-from-institutional-design-to-control-logic-optimization-and-code-generation",level:3},{value:"Cross-Cutting Feature: Institutional Description Language Anyone Can Understand",id:"cross-cutting-feature-institutional-description-language-anyone-can-understand",level:3},{value:"1.3 Glossary",id:"13-glossary",level:2}];function d(n){let e={a:"a",h2:"h2",h3:"h3",li:"li",p:"p",ul:"ul",...(0,o.R)(),...n.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(e.h2,{id:"11-purpose-and-scope",children:"1.1 Purpose and Scope"}),"\n",(0,a.jsx)(e.p,{children:"CADL (Contract Architecture Description Language) is a domain-specific\nlanguage (DSL) for formally specifying, verifying, and deploying\ninstitutional designs in System of Systems (SoS). This document presents\nthe CADL language specification (Version 0.3, Draft), covering language\nobjectives, requirements, syntax and semantics definitions, and\ntoolchain design."}),"\n",(0,a.jsx)(e.p,{children:"This document consolidates the specification for CADL implementation\nbased on a survey of SoS research and SoS\narchitecture design studies conducted at the ERTL."}),"\n",(0,a.jsxs)(e.p,{children:["Chapters 1 and 2 describe the goals of the language; what the reference\nimplementation provides today is listed in ",(0,a.jsx)(e.a,{href:"/cadl-spec/docs/spec/roadmap",children:"Chapter 10"}),"\nand ",(0,a.jsx)(e.a,{href:"/cadl-spec/docs/spec/appendix-a-syntax#a12-reference-implementation-status-v03",children:"Appendix A, \xa7A.12"}),"."]}),"\n",(0,a.jsx)(e.h2,{id:"12-background-challenges-of-institutional-design-in-sos",children:"1.2 Background: Challenges of Institutional Design in SoS"}),"\n",(0,a.jsxs)(e.p,{children:["An SoS is a system configuration in which multiple independently\noperated systems cooperate to achieve capabilities that no single system\ncan achieve alone ",(0,a.jsx)(e.a,{href:"/cadl-spec/docs/spec/appendix-b-references",children:"[Maier, 1998]"}),". ",(0,a.jsx)(e.a,{href:"/cadl-spec/docs/spec/appendix-b-references",children:"[ISO/IEC/IEEE 21841:2019]"})," classifies SoS into four\ntypes: Directed, Acknowledged, Collaborative, and Virtual."]}),"\n",(0,a.jsx)(e.p,{children:"Traditional SoS research has focused on control/coordination algorithms\nand technical optimization, but governance and institutional design are\nnow recognized as upper-layer design variables that structurally\ndetermine overall system behavior. However, current SoS institutional\ndesign relies on natural language contracts and agreements, presenting\nthe following challenges."}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Difficulty detecting ambiguity and contradictions: Natural language\ninstitutional descriptions cannot be formally verified for\nconsistency."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Lack of consistency guarantees for institutional updates:\nInstitutional updates accompanying system addition/removal are\nmanual, with no engineering means for consistency checking."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Gap between design and implementation: There are no means to verify\nthat institutional design intent is accurately reflected in\nimplementation."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Absence of institutional parameterization: No framework exists that\ntreats governance structures as quantitatively manipulable\nvariables."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Lack of three-layer integrated description: No language can\nuniformly describe institutions (authority structures), protocols\n(coordination procedures), and algorithms (computational methods)."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Difficulty of non-expert participation: Existing formal methods and\narchitecture description languages presume advanced expertise,\nmaking it difficult for students, enterprise practitioners,\nmunicipal officials, and citizens to actively participate in\ninstitutional design."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(e.p,{children:"In addition to the above challenges, a fundamental motivation for CADL\nis the need to treat SoS institutional design as a computational object.\nThe following three objectives serve as the direct motivation for\ndesigning the CADL language."}),"\n",(0,a.jsx)(e.h3,{id:"objective-1-making-sos-institutional-design-computationally-tractable",children:"Objective 1: Making SoS Institutional Design Computationally Tractable"}),"\n",(0,a.jsx)(e.p,{children:"In real-world SoS, many institutions exist as human tacit knowledge,\ncustoms, and rules of thumb, often without any documentation. For\nexample, household chore-sharing rules, implicit agreements in local\ncommunities, and informal inter-organizational cooperation exist only in\nparticipants' minds, making external observation and analysis extremely\ndifficult."}),"\n",(0,a.jsx)(e.p,{children:"CADL's primary objective is to model and formalize real-world SoS\ninstitutions, including such tacit rules and customs, making them\nmanipulable as computational objects. When institutions exist as\ncomputational data, the following operations become possible."}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Copy and reuse: Effective institutional designs from one context can\nbe copied and adapted to another. For example, a household's\nchore-sharing rules can be transplanted to another household and\nadjusted for family composition."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Integration and composition: Multiple partial institutional\ndescriptions can be integrated to compose larger SoS institutions.\nFor example, delivery robot routing institutions and data sharing\ninstitutions can be merged into a delivery data coordination\ninstitution."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Version control and diff comparison: Track institutional change\nhistory, revert to any point in time, visualize changes as diffs,\nand identify the scope of impact."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Search and classification: Search repositories of accumulated\ninstitutional descriptions for similar patterns and recommend reuse\ncandidates."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Tacit knowledge elicitation: Through human interviews and AI\nanalysis of observational data, implicit rules are formalized as\nCADL descriptions. This creates a common foundation for sharing,\ndiscussing, and improving institutions."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(e.h3,{id:"objective-2-computing-institutional-violations-and-contradictions",children:"Objective 2: Computing Institutional Violations and Contradictions"}),"\n",(0,a.jsx)(e.p,{children:"If institutions are formally described, it becomes possible to\ncomputationally verify consistency and detect violations at runtime.\nCurrently, contradictions between institutions (e.g., one contract\nmandates information sharing while another prohibits it for privacy\nprotection) can only be checked manually, and oversights become\ninevitable as SoS scale increases."}),"\n",(0,a.jsx)(e.p,{children:"CADL's second objective is to automate institutional contradiction\ndetection and violation monitoring through computational power. This\nencompasses the following two aspects."}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:'AI-integrated design support: AI such as LLMs receives CADL\ndescriptions as input and automatically generates contradiction\ndetection, correction proposals, and institutional improvement\nsuggestions. When asked in natural language "Are these rules\ncontradictory?", AI responds based on CADL\'s formal semantics. In\nthe future, a workflow will be realized where CADL descriptions are\nautomatically generated from natural language requests, formally\nverified, and deployed.'}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Human decision support: Visualize institutional contradictions and\npotential problems to enable informed decisions by human institution\ndesigners. Quantitatively present contradiction severity and impact\nscope, supporting prioritization of corrections. Simulate\ninstitutional changes (what-if analysis) to understand impacts in\nadvance."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(e.h3,{id:"objective-3-automatic-conversion-from-institutional-design-to-control-logic-optimization-and-code-generation",children:"Objective 3: Automatic Conversion from Institutional Design to Control Logic, Optimization, and Code Generation"}),"\n",(0,a.jsx)(e.p,{children:"Once institutional design is described in a formal language and\nverification is complete, the natural next step is to automatically\ngenerate control logic and executable code from institutional\ndescriptions. Currently, there is a large gap between institutional\ndesign (policy documents) and implementation (code), with no guarantee\nthat design intent is correctly reflected in implementation."}),"\n",(0,a.jsx)(e.p,{children:"CADL's third objective is to provide a conversion pipeline from\ninstitutional descriptions to executable artifacts. Specifically, the\nfollowing conversions are envisioned."}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Automatic conversion from institutions to control logic:\nAutomatically generate each actor's control logic (state machines,\nevent handlers, coordination protocol implementations) from CADL\ncontract and protocol definitions. For example, generate skeleton\ncode for DISPATCHER assignment algorithms and ROBOT route-following\nlogic from a robot delivery system's institutional description."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Institutional parameter optimization: Automatically tune\ninstitutional parameter values (alpha, beta, lambda, etc.) through\nsimulation or mathematical optimization. Explore optimal parameter\ncombinations for changing environmental conditions and automatically\nconstruct regime maps."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Runtime code generation: Automatically generate contract monitoring\ncode (assume/guarantee satisfaction checks), protocol execution\nengines, and metrics collection code in target languages (Python,\nTypeScript, Solidity, etc.)."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Integration with assurance cases: Automatically incorporate\ninstitutional verification results as evidence in assurance cases\n(safety arguments) and export to IEC 62853 agreement description\ndatabases."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(e.h3,{id:"cross-cutting-feature-institutional-description-language-anyone-can-understand",children:"Cross-Cutting Feature: Institutional Description Language Anyone Can Understand"}),"\n",(0,a.jsx)(e.p,{children:'As a cross-cutting feature spanning all three objectives, CADL\nemphasizes that "anyone from students to enterprise practitioners,\nmunicipal officials, and local residents can understand the intent of\ninstitutional descriptions and participate in institutional design."\nSoS institutional design is a process involving diverse stakeholders\nbeyond just engineers, and if the description language can only be read\nby a small number of specialists, democratization of institutional\ndesign cannot be achieved.'}),"\n",(0,a.jsx)(e.p,{children:"To achieve this universal readability, CADL adopts the following\napproaches."}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"YAML-based declarative syntax: Adopts indent-based descriptions that\nallow intuitive structural understanding even without programming\nexperience, prioritizing readable syntax over JSON/XML."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Vocabulary close to natural language: Uses vocabulary that directly\nreflects institutional concepts such as authority, responsibility,\nand incentive, while minimizing exposure to formal method notation."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Graduated description levels: Three levels are provided: (1)\nOverview level (descriptions close to natural language, entry point\nfor AI auto-generation), (2) Design level (parameter and constraint\ndefinitions), (3) Verification level (formal assume-guarantee\ndescriptions), enabling participation according to user expertise."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:"Visualization: Automatically generate diagrams (authority structure\ndiagrams, protocol sequence diagrams, regime maps) from CADL\ndescriptions, enabling non-technical users to visually grasp\ninstitutional overviews."}),"\n"]}),"\n",(0,a.jsxs)(e.li,{children:["\n",(0,a.jsx)(e.p,{children:'AI-assisted barrier reduction: Through LLM-mediated CADL description\ngeneration, modification, and explanation in natural language,\nprovide an environment where "institutions can be described by\ncommunicating intentions in natural language without knowing CADL\nsyntax."'}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(e.p,{children:'Integrating these three objectives with the cross-cutting feature of\nuniversal readability, CADL\'s vision is the establishment of an\nengineering cycle for institutional design: "formalize real-world\ninstitutions in a form everyone can understand, verify and improve them\nthrough computation, and automatically convert them into executable\nform." This can be positioned as extending the model-driven development\n(MDD) approach from software engineering to the SoS institutional design\ndomain, while simultaneously broadening participation from specialists\nto society as a whole.'}),"\n",(0,a.jsx)(e.h2,{id:"13-glossary",children:"1.3 Glossary"}),"\n",(0,a.jsxs)(e.p,{children:["This document uses many technical terms. The ",(0,a.jsx)(e.a,{href:"/cadl-spec/docs/spec/glossary",children:"Glossary"})," defines them by topic \u2014 basic concepts, institutional design, the institutional parameters \u03B1, \u03B2 and \u03BB, institutional dynamics, verification and code generation, and the SoS types and related standards \u2014 with plain explanations and, where it helps, concrete examples."]})]})}function u(n={}){let{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,a.jsx)(e,{...n,children:(0,a.jsx)(d,{...n})}):d(n)}},8453(n,e,i){i.d(e,{R:()=>s,x:()=>r});var t=i(6540);let a={},o=t.createContext(a);function s(n){let e=t.useContext(o);return t.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function r(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(a):n.components||a:s(n.components),t.createElement(o.Provider,{value:e},n.children)}}}]);